import{_ as a,o,c as r,ag as t}from"./chunks/framework.TQKaXlFR.js";const m=JSON.parse('{"title":"定时任务与执行日志","description":"","frontmatter":{},"headers":[],"relativePath":"features/scheduler.md","filePath":"features/scheduler.md"}'),i={name:"features/scheduler.md"};function d(l,e,c,n,s,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="定时任务与执行日志" tabindex="-1">定时任务与执行日志 <a class="header-anchor" href="#定时任务与执行日志" aria-label="Permalink to &quot;定时任务与执行日志&quot;">​</a></h1><p>入口为 <strong>运行维护 → 定时任务</strong>及任务日志页面。平台身份和 <code>monitor:job:*</code> / <code>monitor:jobLog:*</code> 控制管理与日志动作。任务只能选择服务端显式注册的handler，不能输入Java类名、Bean表达式或任意调用目标。</p><h2 id="新建与运行" tabindex="-1">新建与运行 <a class="header-anchor" href="#新建与运行" aria-label="Permalink to &quot;新建与运行&quot;">​</a></h2><ol><li>读取处理器列表，选择handlerKey。首次检查可用无业务副作用的 <code>system.noop</code>，参数只能是 <code>{}</code>。</li><li>填写任务名、组、cronExpression、timeZone、handlerParams、misfirePolicy及concurrent；时区是明确的区域名称。</li><li><code>misfirePolicy</code>只接受2（补执行一次）或3（跳过）；<code>status</code>0启用、1暂停；concurrent按界面0/1选项提交。</li><li>保存后查看nextFireTime。编辑现有任务不同时修改status，启停走独立状态接口。</li><li>“执行一次”返回持久化fireId；查看执行记录直到结果完成，不能把返回ID当作成功完成。</li></ol><h2 id="执行记录" tabindex="-1">执行记录 <a class="header-anchor" href="#执行记录" aria-label="Permalink to &quot;执行记录&quot;">​</a></h2><p>fire状态为 <code>CLAIMED/SUCCEEDED/FAILED/SKIPPED/CANCELLED</code>，触发类型为 <code>MANUAL/SCHEDULED</code>。记录含attemptCount、scheduledFireTime、startedAt、completedAt、resultSummary。记录查看、删除与清理有独立日志权限，清理前确认筛选与保留要求。</p><h2 id="正常结果与恢复" tabindex="-1">正常结果与恢复 <a class="header-anchor" href="#正常结果与恢复" aria-label="Permalink to &quot;正常结果与恢复&quot;">​</a></h2><p>合法启用任务显示下一次触发时间；实际成功以SUCCEEDED记录为准。未知handler、非JSON参数、无效cron/时区或不支持的枚举在保存阶段拒绝。失败时先看安全结果摘要并修正处理器配置；不要直接修改持久化fire状态伪造重试。并发/补偿策略不能作为业务天然幂等的保证；扩展处理器仍需自己的去重约束。</p><p>当前是平台调度，不是租户任意脚本执行平台。开发处理器见<a href="/xinghui-admin-vue3/docs/development/scheduler-handler.html">调度扩展</a>。</p><h2 id="源码依据" tabindex="-1">源码依据 <a class="header-anchor" href="#源码依据" aria-label="Permalink to &quot;源码依据&quot;">​</a></h2><ul><li>前端：<code>apps/web-ele/src/api/monitor/job.ts</code>、<code>apps/web-ele/src/views/monitor/job/index.vue</code>、<code>apps/web-ele/src/views/monitor/jobLog/index.vue</code>。</li><li>后端：<code>system-admin/src/main/java/com/xinghuiTec/quartz/controller/SysJobController.java</code>、<code>quartz/controller/SysJobLogController.java</code>、<code>quartz/handler/JobHandlerRegistry.java</code>（均从同一Java源码根定位）。</li></ul>',11)])])}const p=a(i,[["render",d]]);export{m as __pageData,p as default};
